code='''def transform(grid):
    rows, cols = len(grid), len(grid[0])
    cells = {(r, c) for r in range(rows) for c in range(cols) if grid[r][c] == 8}
    pieces = []
    for r in range(rows - 1):
        for c in range(cols - 1):
            block = {(r, c), (r + 1, c), (r, c + 1), (r + 1, c + 1)}
            if block <= cells:
                pieces.append((block, 1))
            for missing, color in (((r, c), 2), ((r + 1, c), 3),
                                   ((r, c + 1), 4), ((r + 1, c + 1), 5)):
                piece = block - {missing}
                if piece <= cells:
                    pieces.append((piece, color))

    def cover(remaining):
        if not remaining:
            return []
        cell = min(remaining, key=lambda point: sum(
            point in piece and piece <= remaining for piece, _ in pieces))
        for piece, color in pieces:
            if cell in piece and piece <= remaining:
                rest = cover(remaining - piece)
                if rest is not None:
                    return [(piece, color)] + rest
        return None

    selected = cover(cells)
    if selected is None:
        raise ValueError("The 8-cells cannot be tiled by the observed shapes")
    output = [[0] * cols for _ in range(rows)]
    for piece, color in selected:
        for r, c in piece:
            output[r][c] = color
    return output
'''
